with base as (select *, case when method in ('paypal', 'bank_transfer') then 'Core' else 'Other' end as method_group, substring(method, 1, 3) as method_prefix, coalesce(method, 'OTHER') as method_filled from payments where method is not null) select * from (select status, order_id, method, amount from base) src pivot (max(amount) as amount for method in ('card' as card, 'promptpay' as promptpay))
